  cameraPosition: vec4f,
  topColorIntensity: vec4f,
  horizonColorPosition: vec4f,
  bottomColorSoftness: vec4f,
  sunDirectionRadius: vec4f,
  sunColorGlow: vec4f,
  dither: vec4f,
